INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129142, 'ruRU', '', 'Прошу прощения за беспокойство, $n, но есть какие-нибудь новости? Стражники иногда проходят мимо, но дают мало информации.', 24330),
(129143, 'ruRU', '', 'Подожди! Подожди! Есть новости, $n? Многие из нас с тревогой ждут каких-либо вестей.', 24330),
(129165, 'ruRU', '', 'Держись того, что знаешь, Икс. Нет смысла строить предположения. А теперь оживись, у нас гость.', 24330),
(129166, 'ruRU', '', 'Наши покровители весьма любят наши товары. Я уверен, что если придёт время, они не замедлят... ох! Добро пожаловать в лавку, $n.', 24330),
(129167, 'ruRU', '', 'Как там дела, $n? При таком количестве покупателей сложно успевать выполнять все заказы. Надеюсь, всё в порядке.', 24330),
(129168, 'ruRU', '', 'Почему тебе так нравятся Осколки Пустоты?', 24330),
(129170, 'ruRU', '', 'Ты ведь на самом деле не знаешь, для чего они, да?', 24330),
(129180, 'ruRU', '', 'А демоны боятся щекотки?', 24330),
(129182, 'ruRU', '', 'Буду считать это согласием.', 24330),
(129183, 'ruRU', '', 'Выглядит забавно - вечно парить в воздухе.', 24330),
(129185, 'ruRU', '', 'Эй, Иксти. Когда у тебя день рождения? Надо устроить праздник!', 24330),
(129187, 'ruRU', '', 'Так... На следующей неделе?', 24330),
(129190, 'ruRU', '', 'Конечно! Как мне это сделать?', 24330),
(129192, 'ruRU', '', 'Ох, та светящаяся штучка? Я её потерял.', 24330),
(129203, 'ruRU', '', 'Полагаю, мне стоит убедиться, что Кузня Скверны ремонтируется должным образом. Увидимся там, Убийцса.', 24330),
(129214, 'ruRU', '', 'С Убийцей, что ведёт нас, Легион ОБЯЗАТЕЛЬНО падёт! Давайте воспользуемся этим моментом, чтобы отпраздновать нашу победу!', 24330),
(129215, 'ruRU', '', 'А теперь точите клинки для грядущих битв! Иллидари одержат победу!', 24330),
(129216, 'ruRU', '', 'Мои оковы на месте, герой! Заманите демона в ловушку, чтобы изгнать тварь!', 24330),
(129239, 'ruRU', '', 'Запасы энергии Кузни Скверны на исходе, Убийца. Энергия скверны вокруг Гробницы может восполнить наши силовые ядра, и тебе удастся подняться на тех гейзерах.', 24330),
(129240, 'ruRU', '', 'Я добавлю это к нашим запасам. Ещё раз спасибо, Убийца!', 24330),
(129241, 'ruRU', '', 'Хм? С чего бы что-то было не так? Проходи мимо!', 24330),
(129243, 'ruRU', '', 'Заходи, $n! Оставь свои тревоги у входа. Стражники уверили нас, что всё в порядке.', 24330),
(129247, 'ruRU', '', 'Небеса темнеют, $n. Надеюсь, ты готов.', 24330),
(129252, 'ruRU', '', 'Ты готов, $n? Некоторые из твоих союзников не очень хорошо справляются с ситуацией.', 24330),
(129254, 'ruRU', '', 'Подготовка - это ключ, $n. Мои товары могут стать твоими - за определённую цену.', 24330),
(129255, 'ruRU', '', 'Я запечатал каждый уровень этого храма, чтобы ни один захватчик не смог спуститься в его глубины. Я никогда не предполагал, что Легион найдёт другой способ прорваться к его тёмному сердцу.', 24330),
(129256, 'ruRU', '', 'Мои защитные обереги теперь преграждают тебе путь. Каждую печать можно открыть только одним из Столпов Созидания. Предупреждаю: демоны не остановятся ни перед чем, чтобы не допустить твоего продвижения.', 24330),
(129258, 'ruRU', '', '$n, сюда! Если услышишь какие-нибудь новости, пожалуйста, сразу дай мне знать. Нужно время, чтобы собрать мои товары.', 24330),
(129259, 'ruRU', '', 'Кому пирожных? Ничто так не прогоняет мрак и тоску, как свежее, вкусное угощение.', 24330),
(129260, 'ruRU', '', 'Столько людей приходят и уходят, заходят в лавки и банк и обратно... Что вообще происходит? Я начинаю нервничать.', 24330),
(129261, 'ruRU', '', 'Я чувствую, как один из повелителей Легиона работает над тем, чтобы воскресить Аватару Саргераса. Если Килджедену удастся наполнить эту оболочку силой Тёмного Титана, я не знаю, сможет ли какая-либо сила в этом мире остановить её.', 24330),
(129272, 'ruRU', '', 'Этот молот выковал древние чудеса и сформировал саму землю. Сегодня он разрывает путы судьбы, что стремятся сокрушить всех нас.', 24330),
(129275, 'ruRU', '', 'Моё эхо провело вас так далеко, как только могло, защитники. В жизни я нёс слишком много бремени один, и эта гордыня обошлась мне дорого. Только вместе вы сможете преодолеть тьму, что ждёт впереди. Прощайте.', 24330),
(129276, 'ruRU', '', 'Из этого камня текли реки и моря, сама жизненная кровь Азерота. Сегодня он омывает тьму, что оставляет шрамы на нашем мире.', 24330),
(129277, 'ruRU', '', 'Эти слёзы безупречной красоты воплощают мечту о том, каким мог бы стать наш мир. Сегодня они очищают ваши сердца для грядущей битвы.', 24330),
(129283, 'ruRU', '', 'Защитник! Нашему судну нужны силовые ядра, заряженные энергией гейзеров скверны. Эти потрёпанные крылья могут оказаться полезными, если ты окажешься в воздухе. Не стесняйся их раскрыть!', 24330),
(129284, 'ruRU', '', 'Столпы Созидания на месте. Вернись в Собор, и я открою тебе древний секрет, который хранит этот храм.', 24330),
(129286, 'ruRU', '', 'Весьма полезно! Понравилось тебе, каково это - парить в воздухе, как охотник на демонов, герой?', 24330),
(129288, 'ruRU', '', 'Эльфы построили этот храм на месте древней силы, хранилище, которое, как я полагал, будет оберегать оболочку моего павшего врага. Но с помощью его ученика Тёмный Титан угрожает вернуться в этот мир более сильным, чем прежде!', 24330),
(129292, 'ruRU', '', 'Наши шпионы заметили демонов, кишащих в этой пещере, Клинок Тени. Мы заложили нужные припасы. Ты знаешь, что делать!', 24330);
